mapper.select:
SELECT id, title, detail, category, priority, due_date, completed, completed_at, deleted_at, created_at, updated_at
FROM todos


        AND title LIKE CONCAT('%', #{keyword}, '%')


        AND category = #{category}


        AND deleted_at IS NULL


        AND deleted_at IS NOT NULL


        AND completed = FALSE


        AND due_date >= #{from}


        AND due_date <= #{to}




        ORDER BY due_date DESC


        ORDER BY due_date ASC



    LIMIT #{limit} OFFSET #{offset}
